L19_1.m_Talk_ENG = "<color=#ffd34c>Do what thou wilt. For it shall be thy law.</color>"
L19_1.m_Talk_TWN = "<color=#ffd34c>做你所願，這就是你的法則。</color>"
L19_1.m_Talk_SCN = "<color=#ffd34c>做你所愿，这就是你的法则。</color>"
L19_1.m_Talk_DEU = "<color=#ffd34c>Do what thou wilt. For it shall be thy law.</color>"
L19_1.m_Talk_FRA = "<color=#ffd34c>Do what thou wilt. For it shall be thy law.</color>"
