L21_1.m_Talk_KOREA = "당신이 이 세계에서 저질렀던 그 거짓된 의식을."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "あなたがこの世界で犯したあの偽りの儀式を。"
L21_1.m_Talk_ENG = "That false ritual you carried out in this world."
L21_1.m_Talk_TWN = "你在這個世界上犯下的那個虛假的儀式。"
L21_1.m_Talk_SCN = "你在这个世界上犯下的那个虚假的仪式。"
L21_1.m_Talk_DEU = "That false ritual you carried out in this world."
L21_1.m_Talk_FRA = "That false ritual you carried out in this world."
