L23_1[2] = L25_1
L22_1.m_CharScale = L23_1
L22_1.m_CharScaleTime = 0.01
L22_1.m_Talk_KOREA = "그리고 당신이 수많은 세계에서 수없이 반복해 왔던 어리석은 만행들을……."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "そして、あなたが多くの世界で、何度となく繰り返してきた愚かな蛮行を……"
L22_1.m_Talk_ENG = "And all the foolish atrocities you've repeated across countless worlds..."
L22_1.m_Talk_TWN = "還有你在無數個世界中無數次重複過的愚蠢暴行……"
L22_1.m_Talk_SCN = "还有你在无数个世界中无数次重复过的愚蠢暴行……"
L22_1.m_Talk_DEU = "And all the foolish atrocities you've repeated across countless worlds..."
L22_1.m_Talk_FRA = "And all the foolish atrocities you've repeated across countless worlds..."
