L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "ですが、私はもうわかっているのです。"
L24_1.m_Talk_ENG = "But now, I finally understand."
L24_1.m_Talk_TWN = "但是現在我知道了。"
L24_1.m_Talk_SCN = "但是现在我知道了。"
L24_1.m_Talk_DEU = "But now, I finally understand."
L24_1.m_Talk_FRA = "But now, I finally understand."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT4_INTERLUDE2@17#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 611
L25_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "ALEISTER_SWANSONG_NPC_QM"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "당신이 무대에서 맡은 역할은 <color=#ffd34c>교황</color>……."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "あなたの舞台での役は<color=#ffd34c>教皇</color>……"
L25_1.m_Talk_ENG = "Your role on the stage is the <color=#ffd34c>Hierophant</color>..."
L25_1.m_Talk_TWN = "你在舞台上扮演的角色是<color=#ffd34c>教皇</color>……"
L25_1.m_Talk_SCN = "你在舞台上扮演的角色是<color=#ffd34c>教皇</color>……"
L25_1.m_Talk_DEU = "Your role on the stage is the <color=#ffd34c>Hierophant</color>..."
L25_1.m_Talk_FRA = "Your role on the stage is the <color=#ffd34c>Hierophant</color>..."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP13_ACT4_INTERLUDE2@18#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 611
L26_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "ALEISTER_SWANSONG_NPC_QM"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "어느 세계에서든 높은 지위와 지식을 손에 넣지만, 어떤 세계에서도 그것에 만족하지 못하죠."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "どの世界でも高い地位と知識を手に入れますが、どの世界でもそれに満足できない。"
L26_1.m_Talk_ENG = "In every world, you attain status and knowledge, yet in none are you ever satisfied."
L26_1.m_Talk_TWN = "無論在哪個世界，你都能獲得高位和知識，但在任何世界，都無法對此感到滿足。"
L26_1.m_Talk_SCN = "无论在哪个世界，你都能获得高位和知识，但在任何世界，都无法对此感到满足。"
L26_1.m_Talk_DEU = "In every world, you attain status and knowledge, yet in none are you ever satisfied."
L26_1.m_Talk_FRA = "In every world, you attain status and knowledge, yet in none are you ever satisfied."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP13_ACT4_INTERLUDE2@19#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 611
L27_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "ALEISTER_SWANSONG_NPC_QM"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "그 탐욕의 끝에 금기를 범하고, 신적 존재에 다다르려 하는 것이 당신의 운명."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "その貪欲の果てに禁忌を犯し、神的存在にたどり着こうとするのがあなたの運命。"
L27_1.m_Talk_ENG = "At the end of your greed, you touch taboo, striving to become divine. That is your fate."
L27_1.m_Talk_TWN = "在那貪婪的盡頭，觸犯禁忌，試圖達到神的境界是你的命運。"
L27_1.m_Talk_SCN = "在那贪婪的尽头，触犯禁忌，试图达到神的境界是你的命运。"
L27_1.m_Talk_DEU = "At the end of your greed, you touch taboo, striving to become divine. That is your fate."
L27_1.m_Talk_FRA = "At the end of your greed, you touch taboo, striving to become divine. That is your fate."
