L41_1.m_Talk_KOREA = "……경위님, 시간이 꽤 지났습니다."
L41_1.m_fTalkTime = 0.03
L41_1.m_Talk_JPN = "……警部補、時間がだいぶ過ぎております。"
L41_1.m_Talk_ENG = "...Lieutenant, it's been quite a while."
L41_1.m_Talk_TWN = "……警衛，時間已經過了很久。"
L41_1.m_Talk_SCN = "……警卫，时间已经过了很久。"
L41_1.m_Talk_DEU = "...Lieutenant, it's been quite a while."
L41_1.m_Talk_FRA = "...Lieutenant, it's been quite a while."
L42_1 = {}
L42_1.m_CutScenKey_Talk = "EP13_ACT4_INTERLUDE2@26#Talk"
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
