L42_1.m_CharStrID = "POLICE_SWANSONG_NPC_NULL"
L42_1.m_Pos = "C"
L43_1 = "이렇게나 시간이 지났는데, <color=#ffd34c>총성</color>이 울리지 않는다는 건……."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "これほど時間が過ぎても、<color=#ffd34c>銃声</color>が聞こえないということは……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "So much time has passed, and we haven't heard a single <color=#ffd34c>gunshot</color>..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "時間已經過去這麼久了，<color=#ffd34c>槍聲</color>卻沒有響起……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "时间已经过去这么久了，<color=#ffd34c>枪声</color>却没有响起……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "So much time has passed, and we haven't heard a single <color=#ffd34c>gunshot</color>..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "So much time has passed, and we haven't heard a single <color=#ffd34c>gunshot</color>..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
