L43_1.m_CharStrID = "POLICE_SWANSONG_NPC_NULL"
L43_1.m_Pos = "C"
L44_1 = "설마, 모리어티 교수가 이미 작전을 눈치채고 도주한 게 아닐까요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "モリアーティ教授がすでに作戦に気づいて逃げたのではないでしょうか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Could it be Professor Moriarty caught wind of the operation and fled?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "難道莫里蒂教授已經察覺到我們的計畫並逃走了嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "难道莫里亚蒂教授已经察觉到我们的计划并逃走了吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Could it be Professor Moriarty caught wind of the operation and fled?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Could it be Professor Moriarty caught wind of the operation and fled?"
