L6_1 = "런던 제일의 프리마돈나를 이렇게 험하게 부리는 건 당신 밖에 없을 거예요, 애버라인."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ロンドン一のプリマドンナをこんなにこき使うのはあなただけですよ、アバーライン。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "No one else would treat London's top prima donna like this but you, Abberline."
L5_1.m_Talk_ENG = L6_1
L6_1 = "這麼粗暴的對待倫敦第一的女主角的人只有你，艾伯林。"
