L16_1 = "의외로 탐정은 논리에 앞서, 직관을 우선해야 하는 경우가 있어."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "時として、探偵は論理よりも直観を優先しなければならない。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "There are times when a detective must trust his instincts over logic."
L15_1.m_Talk_ENG = L16_1
L16_1 = "其實偵探有時需要優先依靠直覺，而不是邏輯。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "其实侦探有时需要优先依靠直觉，而不是逻辑。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "There are times when a detective must trust his instincts over logic."
L15_1.m_Talk_DEU = L16_1
