L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "특히, 나 같이 조직력이 없는 자문 탐정의 경우에는 더욱 그렇다네."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "特に、私のように組織力のない諮問探偵の場合にはなおさらだ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Especially for someone like me, a consulting detective with no real team."
L16_1.m_Talk_ENG = L17_1
L17_1 = "尤其是像我這樣沒有組織力的顧問偵探，更是如此。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "尤其是像我这样没有组织力的顾问侦探，更是如此。"
