L18_1 = "현장에 도착해서 가장 먼저 느낀 감각이 곧 진상으로 이어지는 경우가 대부분이거든."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "現場に到着し、真っ先に感じた感覚が真相に繋がることが多いからな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Usually, that gut feeling I get upon arriving at a scene leads straight to the truth."
L17_1.m_Talk_ENG = L18_1
L18_1 = "到達現場後，最先感受到的感覺大多會直接指向真相。"
