L48_1 = "<color=#ffd34c>만월의 밤. 황금으로 향하는 순례를 마칠 때, 이 땅의 천사가 강림하리라.</color>"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "<color=#ffd34c>満月の夜。黄金へ向かう巡礼を終える時、この地の天使が降臨するであろう。</color>"
L47_1.m_Talk_JPN = L48_1
L48_1 = "<color=#ffd34c>On the night of the full moon. When the pilgrimage to gold is complete, an angel shall descend upon this land.</color>"
L47_1.m_Talk_ENG = L48_1
L48_1 = "<color=#ffd34c>滿月之夜，當黃金朝聖完成時，天使將降臨這片大地。</color>"
L47_1.m_Talk_TWN = L48_1
L48_1 = "<color=#ffd34c>满月之夜。当通往黄金的朝圣结束时，这片土地的天使将降临。</color>"
L47_1.m_Talk_SCN = L48_1
L48_1 = "<color=#ffd34c>On the night of the full moon. When the pilgrimage to gold is complete, an angel shall descend upon this land.</color>"
L47_1.m_Talk_DEU = L48_1
L48_1 = "<color=#ffd34c>On the night of the full moon. When the pilgrimage to gold is complete, an angel shall descend upon this land.</color>"
L47_1.m_Talk_FRA = L48_1
