L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "黄金へ向かう巡礼は、深夜の殺人鬼が行う儀式の手順のことだ……！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The pilgrimage to gold refers to the ritual sequence carried out by the Midnight Killer...!"
