L8_1 = "당장 경관들과 함께 이 명부에서 생일이 7월 23일부터 8월 22일까지인 여성을 전부 찾아 신병을 보호하도록 해."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "今すぐに警官を動員し、このリストから誕生日が7月23日から8月22日の間にある女性を全て探して、保護するように。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Gather the officers and locate every woman on this list born between July 23 and August 22. Put them under protective custody immediately."
L7_1.m_Talk_ENG = L8_1
L8_1 = "立刻召集所有警員，找出名單上所有出生日期在7月23日至8月22日之間的女性，立刻保護她們。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "立刻和警官们一起，从这个名单中找出生日在7月23日至8月22日之间的所有女性，并保护她们的安全。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Gather the officers and locate every woman on this list born between July 23 and August 22. Put them under protective custody immediately."
L7_1.m_Talk_DEU = L8_1
