L10_1 = "그래, 사자자리라네. 그리고 심야의 살인마의 다음 표적이지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ああ、獅子座だ。そして深夜の殺人鬼の次のターゲットでもある。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Yes, Leos. One of them will be the Midnight Killer's next target."
