L44_1.m_CharStrID = L45_1
L45_1 = "왜냐하면 저는 망각의 여신으로부터 미움을 받은 몸이거든요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "私は忘却の女神から嫌われた身ですので。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Understandable, really. I'm someone cursed by the goddess of oblivion."
L44_1.m_Talk_ENG = L45_1
L45_1 = "畢竟我是被遺忘女神詛咒的人。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "因为我是被遗忘女神所厌恶的存在。"
