L46_1 = "SWAN_SIX_NULL_QM"
L45_1.m_CharStrID = L46_1
L46_1 = "모든 것이 방금 일어났던 일처럼 생생한데, 벌써 이렇게나 오랜 시간이 흘러 버렸죠."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "何もかもが、ついさっきのことのように鮮明なのに。もうこんなにも時間が流れてしまいましたね。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Everything still feels fresh, like it happened yesterday, but so much time has passed."
L45_1.m_Talk_ENG = L46_1
L46_1 = "一切依舊歷歷在目，彷彿昨日發生，可時間卻已流逝許久。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "一切都像刚刚发生的一样鲜活，但已经过去了这么长的时间。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Everything still feels fresh, like it happened yesterday, but so much time has passed."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Everything still feels fresh, like it happened yesterday, but so much time has passed."
L45_1.m_Talk_FRA = L46_1
