L3_1 = "SWAN_SIX_NULL_QM"
L2_1.m_CharStrID = L3_1
L3_1 = "왜냐하면 당신은 아무것도 몰랐던 절 기만했고, 당신의 복수는 결국 세계를 무너트렸으니까."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あなたは何もわからなかった私を欺いたし、あなたの復讐は結局世界を崩壊させたから。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You deceived me when I knew nothing. And your revenge destroyed the world."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你在我一無所知時欺騙了我，你的復仇毀滅了這個世界。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "因为你欺骗了什么都不知道的我，而你的复仇最终摧毁了整个世界。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "You deceived me when I knew nothing. And your revenge destroyed the world."
L2_1.m_Talk_DEU = L3_1
L3_1 = "You deceived me when I knew nothing. And your revenge destroyed the world."
